sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({ api, helpers }) {
  try {
    // Fetching content dynamically from "Dynamic Sys Reader"
    const contentTree =  api.data.dynamic_sys_reader_1.output;

    if (!contentTree || !Array.isArray(contentTree)) {
      throw new Error("Invalid or missing contentTree data.");
    }

    // Build the HTML with professional bullet and header color
    let html = `
      <style>
        .card {
          background: linear-gradient(135deg, #f5f7fa 0%, #e4e9f0 100%);
          border-radius: 12px;
          padding: 10px,20px,20px,20px;
          box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
          font-family: 'Roboto', 'Arial', sans-serif;
        }
        .card-header {
          padding: 20px;
          font-size: 28px;
          font-weight: 700;
          color: #8875c7;
          text-align: center;
          border-bottom: 2px solid #c5cae9;
        }
        .card-body {
          padding: 25px;
        }
        .parent-cards-container {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          gap: 20px;
        }
        .parent-card {
          border: 1px solid #e0e0e0;
          border-radius: 10px;
          background: #ffffff;
          box-shadow: 0 4px 10px rgba(0, 0, 0, 0.05);
          transition: transform 0.3s ease, box-shadow 0.3s ease;
        }
        .parent-card:hover {
          transform: translateY(-5px);
          box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
        }
        .parent-header {
          background: #98c1d9;
          padding-top: 15px;
          font-size: 15px;
          font-weight: 500;
          color: #ffffff;
          text-align: center;
          border-bottom: 1px solid #4fc3f7;
          height: 50px;
          line-height: 20px;
          box-sizing: border-box;
        }
        .children-container {
          padding: 20px;
          background: linear-gradient(to bottom, #f0f4f7 0%, #ffffff 100%);
          border-top: 1px solid #e0e0e0;
        }
        .child-item {
          font-size: 16px;
          font-weight: 500;
          margin-bottom: 15px;
          color: #37474f;
          line-height: 1.6;
          padding-left: 15px;
          border-left: 4px solid #26a69a;
          background: #f7fafc;
          border-radius: 4px;
          display: flex;
          align-items: center;
          text-align: left;
        }
        // .child-item::before {
        //   content: "•";
        //   color: #0288d1;
        //   font-weight: bold;
        //   margin-right: 12px;
        //   font-size: 16px;
        // }
        .child-item:last-child {
          margin-bottom: 0;
        }
      </style>
      <div class="card">
        <div class="card-header">Certifying Software Models</div>
        <div class="card-body">
          <div class="parent-cards-container">
    `;

    contentTree.forEach(parent => {
      html += `
        <div class="parent-card">
          <div class="parent-header">${parent.label}</div>
          <div class="children-container">
      `;

      parent.children.forEach(child => {
        html += `<div class="child-item">${child.label}</div>`;
      });

      html += `</div></div>`;
    });

    html += `</div></div></div>`;

    return html;
  } catch (error) {
    return `<div style="color: red; font-weight: bold;">Error: ${error.message}</div>`;
  }
}
